 private void powerCards(){Intent battery=getContext().registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=battery==null?-1:battery.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=battery==null?100:battery.getIntExtra(BatteryManager.EXTRA_SCALE,100);int plugged=battery==null?0:battery.getIntExtra(BatteryManager.EXTRA_PLUGGED,0);detail("Battery level",level<0?"Unavailable":Math.round(level*100f/Math.max(1,scale))+"% · "+(plugged!=0?"Plugged in":"On battery"));PowerManager manager=getContext().getSystemService(PowerManager.class);card("Energy saver",manager!=null&&manager.isPowerSaveMode()?"On":"Off","power",()->open.accept("setting:android:battery"));card("Power mode","Battery and performance preferences","power",()->open.accept("setting:android:battery"));card("Screen, sleep & timeout","Change when the Android display turns off","display",()->open.accept("setting:android:display"));card("Battery usage","See Android's battery history and app usage","time",()->open.accept("setting:android:battery"));}
