 void startFolders(){String[] names={"Settings","Documents","Downloads","Music","Pictures","Videos"};String saved=store.prefs.getString("eleven_start_folders","");boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++)checked[i]=Arrays.asList(saved.split(",")).contains(names[i]);Aero.dialog(getContext()).setTitle("Folders next to Power").setMultiChoiceItems(names,checked,(d,n,value)->checked[n]=value).setPositiveButton("Save",(d,n)->{List<String> rows=new ArrayList<>();for(int i=0;i<names.length;i++)if(checked[i])rows.add(names[i]);store.prefs.edit().putString("eleven_start_folders",String.join(",",rows)).apply();if(getContext() instanceof MainActivity)((MainActivity)getContext()).refreshTen();}).setNegativeButton("Cancel",null).show();}
