  if(width>=dp(580)){View icon=new TenStyle.Glyph(getContext(),kind,categoryColor(kind));LayoutParams ip=new LayoutParams(dp(20),dp(20));ip.setMargins(dp(9),0,dp(10),0);row.addView(icon,ip);}
